import { TopicItem } from '../types';

type Lesson = Pick<TopicItem, 'summary' | 'lessonSections' | 'example' | 'references' | 'quickQuestions'>;
type Seed = [string, string, string, 'certo' | 'errado', string];
const make = (id: string, [summary, example, prompt, correctAnswer, explanation]: Seed, label: string, url: string): Lesson => ({
  summary, lessonSections: [{ heading: 'Conceito-chave', body: summary }], example,
  references: [{ label, url }],
  quickQuestions: [{ id: `${id}-q1`, prompt, source: 'Questão autoral para treino', correctAnswer, explanation }],
});
