const dbSections: Record<number, Array<{ heading: string; body: string }>> = {
  0: [
    { heading: 'Do modelo conceitual ao relacional', body: 'No MER, entidade representa algo sobre o qual se guardam dados; atributo descreve uma propriedade; relacionamento registra associação. Cardinalidade e participação expressam limites: em “cliente faz pedidos”, um cliente pode ter vários pedidos, enquanto cada pedido pode estar ligado a um cliente. Ao passar ao modelo relacional, entidades viram tabelas, atributos viram colunas e relações N:M normalmente exigem uma tabela associativa.' },
    { heading: 'Chaves e integridade', body: 'A chave primária identifica cada linha e não admite duplicidade nem valor nulo. A chave estrangeira referencia uma chave candidata de outra tabela e protege a integridade referencial. Uma chave composta usa mais de uma coluna; uma chave substituta simplifica a identificação técnica, mas não elimina a necessidade de restrições sobre valores de negócio.' },
  ],
  1: [
    { heading: 'Dependências e formas normais', body: 'A normalização parte das dependências funcionais: se um atributo determina outro, atualizações devem manter essa relação consistente. Na 1FN, cada posição contém valor atômico no modelo adotado; na 2FN, atributos não-chave dependem da chave inteira, sem dependência parcial de chave composta; na 3FN, evita-se dependência transitiva de atributo não-chave em relação à chave. A decomposição deve preservar informação e, quando possível, dependências.' },
    { heading: 'Anomalias que a decomposição evita', body: 'Redundância pode produzir anomalia de atualização (o mesmo dado muda em alguns registros, mas não em outros), de inserção (um fato não pode ser cadastrado sem outro) ou de exclusão (apagar uma linha remove também um fato que deveria permanecer). Desnormalizar pode ser uma decisão de desempenho, mas requer estratégia explícita para manter consistência.' },
  ],
  2: [
    { heading: 'Operações e leitura de consultas', body: 'Na álgebra relacional, seleção filtra linhas e projeção escolhe colunas; junção combina tuplas relacionadas. Em SQL, pratique a leitura separando FROM/JOIN, WHERE, GROUP BY, HAVING e SELECT. WHERE restringe linhas antes do agrupamento; HAVING filtra grupos depois das agregações. A ordem escrita das cláusulas não é a ordem conceitual de avaliação.' },
    { heading: 'NULL e lógica de três valores', body: 'NULL representa ausência ou desconhecimento e não se compara com igualdade comum: “coluna = NULL” não é o teste correto. Use IS NULL/IS NOT NULL. Comparações envolvendo NULL podem resultar em UNKNOWN; por isso, filtros e NOT IN com valores nulos merecem cuidado. Funções agregadas geralmente ignoram NULL, enquanto COUNT(*) conta linhas.' },
  ],
  3: [
    { heading: 'ACID na prática', body: 'Atomicidade evita confirmar apenas parte de uma unidade lógica; consistência mantém restrições válidas; isolamento controla interferência entre transações concorrentes; durabilidade preserva o que foi confirmado mesmo após falha. COMMIT confirma e ROLLBACK desfaz alterações ainda não confirmadas, conforme o comportamento transacional do SGBD.' },
    { heading: 'Concorrência e isolamento', body: 'Execuções concorrentes podem gerar leitura suja, leitura não repetível ou linhas fantasmas, conforme o nível de isolamento e a implementação. Isolamento mais forte tende a reduzir anomalias, mas pode diminuir concorrência ou exigir bloqueios. A prova costuma cobrar o significado de cada propriedade, não assumir que todo SGBD implementa os níveis de maneira idêntica.' },
  ],
  4: [
    { heading: 'Como avaliar um índice', body: 'Índices mantêm uma estrutura auxiliar que permite localizar linhas sem percorrer toda a tabela em certos planos. B-trees atendem buscas por igualdade e intervalos; índices hash são voltados a igualdade na implementação que os oferece. Seletividade, ordem das colunas em índice composto, filtros, estatísticas e custo de atualização influenciam a escolha do otimizador.' },
    { heading: 'Plano de execução', body: 'Compare o plano estimado com o volume e a distribuição real dos dados. Um índice pode ser ignorado quando a consulta retorna grande parte da tabela, quando a expressão impede seu uso ou quando estatísticas estão desatualizadas. A otimização deve partir da consulta e do workload medido, não da regra “mais índices sempre são melhores”.' },
  ],
  5: [
    { heading: 'Objetos de banco e efeitos', body: 'Uma view expõe o resultado de uma consulta como interface lógica; uma procedure encapsula comandos invocados explicitamente; uma função costuma retornar valor ou conjunto conforme o SGBD; uma trigger é acionada por evento configurado. Esses objetos podem centralizar regras, mas acrescentam dependências que precisam de versionamento, testes, permissões e observabilidade.' },
    { heading: 'DDL e DML', body: 'DDL define ou altera estruturas, como CREATE e ALTER; DML consulta ou modifica dados, como SELECT, INSERT, UPDATE e DELETE. Distinguir linguagem de definição de estrutura e manipulação de registros ajuda a analisar privilégios e efeitos de um comando. Antes de UPDATE ou DELETE, confira o predicado e a quantidade de linhas atingidas.' },
  ],
  6: [
    { heading: 'Administração orientada a evidências', body: 'Administração inclui papéis e privilégios, configuração, capacidade, índices, estatísticas, logs, atualizações, cópias de segurança e recuperação. Diagnostique com métricas e planos de execução antes de mudar parâmetros globais. Teste restauração em ambiente controlado: arquivo de backup existente não comprova que o banco pode ser recuperado dentro dos objetivos definidos.' },
    { heading: 'Diferenças entre produtos', body: 'PostgreSQL e Oracle implementam conceitos relacionais comuns, mas diferem em sintaxe, tipos, ferramentas, catálogo, licenciamento e recursos administrativos. Em questões, não transfira automaticamente um comando ou comportamento específico de um produto para o outro; identifique quando o enunciado pede conceito geral e quando pede detalhe do SGBD.' },
  ],
  7: [
    { heading: 'Quatro famílias NoSQL', body: 'Documentos agrupam campos flexíveis por registro; chave-valor privilegia busca direta por chave; wide-column organiza dados por famílias de colunas; grafos representam nós e arestas para percorrer relações. A escolha começa pelo padrão de acesso, volume, consistência, distribuição e necessidade de consulta, e não por uma suposta superioridade geral sobre o modelo relacional.' },
    { heading: 'Consistência e modelagem', body: 'Soluções distribuídas podem fazer escolhas distintas entre disponibilidade, consistência e tolerância a partições, e cada produto oferece garantias concretas próprias. Modelagem orientada a consultas pode duplicar dados para reduzir leituras; isso exige definir qual cópia é fonte de verdade e como propagar atualizações.' },
  ],
  8: [
    { heading: 'Documentos, coleções e chave-valor', body: 'No MongoDB, documentos BSON ficam em coleções e podem agrupar dados acessados juntos; referências ou incorporação dependem do ciclo de vida, cardinalidade e tamanho. No Redis, estruturas em memória permitem operações rápidas por chave, com expiração e opções de persistência. “Em memória” não significa necessariamente “sem persistência”: configuração e modo de falha importam.' },
    { heading: 'Casos de uso e limites', body: 'Cache reduz leituras repetidas, mas exige política de expiração e tratamento de invalidação. Documento flexível facilita evolução de esquema, mas validação e consistência entre documentos continuam sendo decisões da aplicação. Considere durabilidade, concorrência, memória, replicação e recuperação antes de escolher a tecnologia.' },
  ],
  9: [
    { heading: 'Do texto ao vetor', body: 'Um modelo de embedding transforma uma entrada em vetor numérico para que conteúdos semanticamente próximos possam ser recuperados. O fluxo costuma incluir normalização, divisão em segmentos, geração de embeddings, indexação e busca por vizinhos. O tamanho dos trechos afeta contexto e precisão: segmentos enormes misturam assuntos; segmentos curtos podem perder relações.' },
    { heading: 'Recuperação não é validação', body: 'Metadados e filtros podem restringir a busca por fonte, data, versão ou permissão. A distância vetorial ordena candidatos; não comprova que o trecho responde corretamente nem que uma norma está vigente. Sistemas de recuperação devem avaliar relevância, cobertura, atualização da base e acesso autorizado.' },
  ],
  10: [
    { heading: 'Cópia, réplica e recuperação', body: 'Replicação mantém cópias para disponibilidade ou leitura distribuída, mas pode propagar exclusão lógica, corrupção ou ransomware. Backup preserva versões recuperáveis; recuperação aplica cópias e registros conforme a estratégia. Combine cópias com isolamento de credenciais, proteção contra alteração e testes periódicos de restauração.' },
    { heading: 'RPO, RTO e estratégia', body: 'RPO expressa a perda máxima de dados aceitável medida no tempo; RTO expressa quanto tempo se aceita levar para restabelecer o serviço. A frequência de backup, retenção, replicação e procedimento de recuperação precisam ser compatíveis com essas metas. Faça exercícios que validem integridade e tempo real de retorno.' },
  ],
  11: [
    { heading: 'Papéis, qualidade e ciclo de vida', body: 'Governança de dados distribui responsabilidades entre proprietários, custodiante e usuários; define políticas de acesso, qualidade, classificação, retenção e descarte. Qualidade pode ser observada por dimensões como completude, consistência, validade, unicidade e atualidade, sempre em relação a uma finalidade.' },
    { heading: 'Linhagem e proteção', body: 'Linhagem registra origem, transformação, movimentação e destino dos dados, apoiando auditoria e análise de impacto. A classificação deve acompanhar o dado em repouso, em trânsito e em uso; trilhas de acesso e retenção ajudam a demonstrar controle. Governança não se limita à estrutura técnica do banco.' },
  ],
};
const dbClassroom: Array<[string, string]> = [
  ['Quando transformar um MER, resolva entidades e relacionamentos antes de criar tabelas. Um relacionamento N:M vira tabela associativa com chaves estrangeiras; atributos próprios da relação, como quantidade do item, pertencem a ela. Verifique obrigatoriedade e cardinalidade nos dois sentidos.', 'Use restrições UNIQUE, NOT NULL, CHECK e FOREIGN KEY para formalizar regras que o banco pode garantir. Chave natural tem significado de negócio; chave substituta não substitui as restrições sobre valores únicos reais. Desenhe um exemplo com duas ou três linhas para conferir o modelo.'],
  ['Considere relação Pedido(id, cliente, endereçoCliente, item, produto) com vários itens: repetir dados de cliente multiplica a chance de divergência. Separe Cliente, Pedido e Item; preserve a relação por identificadores e valide a decomposição com dependências funcionais.', 'Desnormalizar pode criar tabela-resumo ou cópia de atributo para leitura; defina qual fonte é autoritativa, como a cópia se atualiza e como detectar divergência. Meça antes de desnormalizar: custo de escrita, consistência e manutenção acompanha a otimização.'],
  ['SQL é declarativa: descreva o conjunto desejado e deixe o otimizador escolher plano. SELECT projeta colunas, WHERE filtra linhas, GROUP BY cria grupos e HAVING filtra grupos; JOIN expressa combinação conforme condição de relacionamento.', 'Ao analisar consulta com COUNT, confira se a junção multiplica linhas e se precisa de DISTINCT. LEFT JOIN preserva linhas sem correspondência; uma condição no WHERE sobre a tabela opcional pode eliminar NULL e aproximar resultado de INNER JOIN.'],
  ['Para transferência, mantenha débito e crédito na mesma transação: valide saldo, atualize ambas as contas e confirme; se uma etapa falhar, reverta tudo. Controle concorrência para que duas requisições não leiam saldo antigo e permitam saque simultâneo indevido.', 'Escolha isolamento e bloqueios conforme invariantes e carga. Deadlock pode ocorrer quando transações esperam recursos em ordem diferente; o SGBD pode abortar uma delas, então a aplicação precisa tratar a falha e eventualmente repetir operação idempotente.'],
  ['Compare plano de execução, estatísticas e volume real; observe varredura sequencial, índice, estimativa de linhas, ordenação e join. Estatísticas desatualizadas podem levar o otimizador a escolher caminho inadequado. Ajuste uma hipótese por vez e meça com dados representativos.', 'Índice composto em (a,b) pode apoiar filtro por a e por a+b, mas nem sempre busca eficiente apenas por b. Função aplicada à coluna, conversão implícita ou padrão de wildcard pode impedir uso esperado. Verifique o plano, não presuma.'],
  ['Trigger pode ser row-level ou statement-level conforme SGBD e evento; ordem, transação e efeito precisam ser conhecidos. Para auditoria, registre ator, horário, operação e valores necessários, evitando cópia ilimitada de dado sensível.', 'Regra escondida em trigger afeta qualquer cliente que altera tabela, mas pode surpreender manutenção e testes. Evite chamada de rede ou operação demorada dentro de trigger; considere constraints, lógica explícita ou mecanismo de auditoria conforme requisito.'],
  ['Rotina administrativa deve começar por métrica e diagnóstico: plano, locks, conexões, buffer, IO, estatística, crescimento e log. Ajuste em janela controlada e valide antes/depois. PostgreSQL e Oracle compartilham conceitos relacionais, mas oferecem catálogo, ferramentas e sintaxe próprios.', 'Configure backup, recuperação point-in-time quando aplicável, usuários e privilégios, atualização e monitoramento. Em produção, preserve capacidade de retorno e teste restauração; parâmetro de memória ou índice não deve ser copiado de outro SGBD sem considerar carga.'],
  ['Escolha modelo NoSQL a partir da consulta e do vínculo: chave-valor para acesso direto; documento para agregado flexível; wide-column para distribuição por chave e consultas previstas; grafo para travessias de relações.', 'Se uma aplicação precisa consultar relações cruzadas arbitrárias, um documento aninhado pode duplicar dados e dificultar consistência. Se precisa buscar documento inteiro por chave e evoluir campos, modelo de documento pode ser adequado. Delimite consistência, índices e atualização.'],
  ['Modele documentos conforme operações: agregado acessado junto pode ficar embutido; relação compartilhada e atualizada frequentemente pode referenciar outro documento. Redis pode servir cache, sessão, fila ou estruturas de dados, dependendo de persistência e configuração.', 'Defina TTL, política de invalidação e comportamento quando cache falha. Em MongoDB, valide esquema e índice para consulta real. Não trate flexibilidade de documento como ausência de modelagem: campos, tamanho e consistência continuam sendo decisões explícitas.'],
  ['No RAG, escolha modelo de embedding compatível com idioma e domínio, segmente documentos preservando contexto, grave metadados e filtre por permissão/data antes da busca. Avalie recall e precisão da recuperação com consultas de referência.', 'Quando a pergunta exige redação exata de artigo, combine busca lexical e vetorial ou consulta estruturada. Registre versão e origem de cada trecho; exclua documento revogado. Similaridade alta sem citação verificável não basta para resposta de prova ou decisão administrativa.'],
  ['Estratégia de cópia pode combinar backup completo/incremental, snapshots, logs transacionais e réplicas, conforme RPO/RTO. Separe cópias por falha e credenciais; proteção imutável ajuda contra alteração maliciosa.', 'Execute restauração completa em ambiente de teste e compare integridade, dependências, tempo e procedimento. Réplica síncrona pode reduzir perda mas introduzir latência; assíncrona pode perder transações recentes. Escolha com requisitos explícitos.'],
  ['Defina papéis: proprietário decide finalidade e classificação; custodiante opera controles; usuário utiliza conforme autorização. Catálogo, dicionário, linhagem e métricas tornam dados compreensíveis e permitem rastrear transformações.', 'Para indicador oficial, documente fonte, regra de cálculo, periodicidade, responsável e qualidade. Se sistemas produzem valores diferentes, resolva semântica e origem antes de copiar dados. Governança liga necessidade institucional a qualidade, acesso e responsabilidade.'],
];
const dbRef = 'https://www.postgresql.org/docs/current/';
export const DEVOPS_DATABASE_CONTENT: Record<string, Lesson> = {
  ...Object.fromEntries(devops.map((seed, index) => { const id = `devops-${index}`; const [mechanics, application, examFocus] = devopsClassroom[index]; const lesson = make(id, seed, 'Documentação Kubernetes', 'https://kubernetes.io/docs/home/'); return [id, { ...lesson, lessonSections: [{ heading: 'Aprofundamento', body: devopsSections[index] }, { heading: 'Funcionamento em detalhe', body: mechanics }, { heading: 'Aplicação passo a passo', body: application }, { heading: 'Distinções e armadilhas', body: examFocus }] }]; })),
  ...Object.fromEntries(db.map((seed, index) => {
    const id = `banco-dados-${index}`;
    const lesson = make(id, seed, 'Documentação PostgreSQL', dbRef);
    const references = index === 6
      ? [...(lesson.references ?? []), {
          label: 'Gran Cursos — Banco de Dados Relacionais, Parte V (SQL, privilégios e índices)',
          url: 'https://drive.google.com/file/d/10vro7pmzPrlkpwbKLOtOl7TLZJcEaUx8/view?usp=sharing',
        }]
      : lesson.references;
    const [application, examFocus] = dbClassroom[index];
    return [id, { ...lesson, references, lessonSections: [...dbSections[index], { heading: 'Aplicação passo a passo', body: application }, { heading: 'Decisão e armadilhas', body: examFocus }] }];
  })),
};

const security: Seed[] = [
  ['Confidencialidade restringe divulgação; integridade protege exatidão e completude; disponibilidade permite acesso oportuno; autenticidade confirma origem/identidade; não repúdio apoia evidência de autoria ou ação.', 'Assinatura digital ajuda a verificar integridade e autoria; redundância e recuperação apoiam disponibilidade.', 'Confidencialidade, integridade e disponibilidade formam a tríade CIA, complementada por autenticidade e não repúdio conforme o contexto.', 'certo', 'Os atributos se complementam e podem ser apoiados por controles diferentes.'],
  ['Risco combina probabilidade e impacto conforme método adotado; vulnerabilidade é fraqueza explorável; incidente é evento que compromete ou ameaça ativos. Gestão inclui identificar, avaliar, tratar, monitorar e responder.', 'Priorize uma falha exposta à internet que afeta dados sensíveis antes de um problema cosmético isolado.', 'Tratamento de risco pode reduzir, evitar, compartilhar ou aceitar risco conforme decisão e tolerância.', 'certo', 'São estratégias usuais; aceitação deve ser deliberada e documentada.'],
  ['Classificação atribui nível de proteção segundo sensibilidade, impacto e requisitos legais/institucionais. Rótulos devem orientar armazenamento, acesso, compartilhamento, transmissão, retenção e descarte.', 'Um documento reservado não deve ser colocado em repositório público mesmo que o link seja difícil de adivinhar.', 'Classificação só tem valor quando associada a regras de tratamento e controles práticos.', 'certo', 'Rótulo sem controle de acesso, circulação e retenção não protege a informação.'],
  ['IAM administra identidades, autenticação, autorização e ciclo de acesso. Use menor privilégio, MFA conforme risco, revisão periódica, segregação de funções e revogação rápida ao mudar vínculo ou atribuições.', 'Uma conta de serviço recebe somente leitura do bucket de que precisa e credenciais são rotacionadas.', 'Autenticação responde quem é a entidade; autorização, o que ela pode fazer.', 'certo', 'São etapas relacionadas, mas distintas do controle de acesso.'],
  ['Criptografia simétrica usa segredo compartilhado; assimétrica usa par de chaves. PKI vincula chaves públicas a identidades por certificados; assinatura digital verifica integridade e autoria; gestão de chaves é crítica.', 'TLS combina mecanismos para negociar sessão protegida e autenticar servidor com certificado.', 'Hash criptográfico, assinatura e criptografia são operações distintas.', 'certo', 'Hash resume dados; assinatura usa chave privada para autenticação/integridade; criptografia visa confidencialidade.'],
  ['OWASP Top 10:2025 destaca riscos como controle de acesso quebrado, configuração insegura, falhas na cadeia de suprimentos, falhas criptográficas, injeção, design inseguro, autenticação, integridade, logging/alertas e tratamento de exceções.', 'Valide autorização no servidor em cada objeto consultado; ocultar botão na interface não impede acesso direto.', 'OWASP Top 10 é documento de conscientização e não uma lista completa de todos os controles de segurança.', 'certo', 'A OWASP descreve o Top 10 como ponto de partida; padrões verificáveis como ASVS são mais abrangentes.'],
  ['APIs devem autenticar, autorizar por recurso, validar entradas, limitar taxa, proteger segredos e registrar eventos. Containers e nuvem exigem imagens confiáveis, configuração segura, isolamento, atualização, IAM mínimo e proteção de metadados.', 'Limite o endpoint de exportação por identidade, escopo e volume; não confie apenas em CORS.', 'CORS não substitui autenticação e autorização no servidor.', 'certo', 'CORS é política de navegador para origem cruzada; não controla acesso de clientes arbitrários ao serviço.'],
  ['Backup preserva dados; continuidade mantém funções críticas durante interrupção; recuperação de desastre restaura sistemas após evento grave. Defina RTO (tempo-alvo) e RPO (perda de dados tolerada) e teste procedimentos.', 'RPO de 15 minutos indica tolerância a perder até esse intervalo de alterações, sob a estratégia definida.', 'Um backup só é confiável quando sua restauração é testada.', 'certo', 'Cópia sem teste pode estar incompleta, corrompida ou inaplicável.'],
  ['Malware é software malicioso; ransomware busca extorquir, frequentemente criptografando ou exfiltrando dados; phishing induz a revelar dados ou executar ação; engenharia social explora confiança e contexto humano.', 'Verifique domínio, remetente e solicitação por canal independente antes de abrir anexo inesperado.', 'Engenharia social pode explorar pessoas sem explorar vulnerabilidade técnica do software.', 'certo', 'Manipulação de processos humanos é parte central desses ataques.'],
  ['Firewall filtra tráfego por regras; antivírus/EDR detecta ou responde a ameaças no endpoint; IDS detecta atividade suspeita; IPS pode bloquear; pentest simula ataque autorizado; análise de vulnerabilidades identifica fraquezas.', 'Use análise automatizada para cobertura ampla e pentest autorizado para validar caminhos exploráveis.', 'IDS normalmente detecta e alerta; IPS pode atuar preventivamente no fluxo de tráfego.', 'certo', 'As funções variam por implementação, mas essa distinção conceitual é útil.'],
  ['Zero Trust evita confiança implícita baseada apenas em localização de rede. Acesso é autenticado e autorizado explicitamente, com contexto, privilégio mínimo e avaliação contínua de identidade, dispositivo e recurso.', 'Usuário na rede interna ainda passa por verificação de identidade e autorização para acessar aplicação sensível.', 'Zero Trust significa que nenhum acesso é permitido em qualquer circunstância.', 'errado', 'O princípio é verificar explicitamente cada acesso, não proibir todo acesso.'],
  ['A família ISO/IEC 27000 reúne normas de gestão e controles de segurança da informação. ISO/IEC 27001 especifica requisitos de sistema de gestão; ISO/IEC 27002 apresenta controles de referência. Versão, escopo e aplicabilidade devem ser verificados.', 'Uma organização certificada em ISO 27001 tem um SGSI auditado dentro de escopo definido.', 'ISO/IEC 27002 é referência de controles e não substitui, por si só, os requisitos de certificação da 27001.', 'certo', 'A 27001 define requisitos certificáveis; a 27002 apoia seleção e implementação de controles.'],
];
const securitySections: Record<number, Array<{ heading: string; body: string }>> = {
  0: [{ heading: 'Atributos e controles', body: 'Associe cada objetivo a controles adequados: confidencialidade a autorização e criptografia; integridade a hash, assinatura, validação e trilha; disponibilidade a redundância, capacidade e recuperação. Autenticidade trata de confirmar identidade ou origem; não repúdio depende de evidências e do contexto jurídico e operacional.' }],
  1: [{ heading: 'Ciclo de gestão de riscos', body: 'Defina escopo e critérios, identifique ativos, ameaças e vulnerabilidades, estime probabilidade e impacto, priorize e escolha tratamento. Registre responsável, prazo, risco residual e aprovação de aceitação. Risco não é sinônimo de vulnerabilidade: uma fraqueza só se traduz em risco quando considerada a possibilidade de exploração e suas consequências.' }],
  2: [{ heading: 'Classificação ao longo do ciclo', body: 'A classificação precisa orientar decisões concretas de acesso, armazenamento, cópia, transmissão, compartilhamento, retenção e descarte. Revise rótulo quando finalidade, sensibilidade ou obrigação legal mudar. Repositórios, backups e exportações também precisam herdar controles compatíveis com o dado que contêm.' }],
  3: [{ heading: 'Ciclo de identidade', body: 'O processo IAM começa com identidade individual e vínculo verificado, concede acesso conforme função ou atributos, revisa privilégios e revoga credenciais no desligamento ou mudança de função. Contas de serviço e privilégios administrativos também precisam de dono, escopo limitado, rotação e monitoramento; MFA reduz o risco de credencial roubada.' }],
  4: [{ heading: 'Chaves e certificados', body: 'Criptografia simétrica é eficiente para grandes volumes, mas exige distribuir o segredo com segurança. Criptografia assimétrica usa par público/privado para troca ou assinatura. Certificado liga uma chave pública a uma identidade por uma cadeia de confiança. Proteja geração, armazenamento, rotação, revogação e descarte das chaves: algoritmo forte não compensa chave exposta.' }],
  5: [{ heading: 'Categorias do OWASP e defesa', body: 'Use o Top 10 como alerta para classes de risco, e complemente a avaliação com requisitos de verificação e testes. Controle de acesso deve ser aplicado no servidor a cada recurso; configuração, dependências, criptografia, autenticação, integridade e logging precisam entrar no ciclo de desenvolvimento e operação.' }],
  6: [{ heading: 'Defesa de APIs e containers', body: 'Para APIs, valide esquema e tamanho de entrada, autentique chamadas, autorize cada objeto e limite consumo. Em containers, reduza privilégios, use imagens verificadas e atualizadas, evite segredos na imagem e restrinja rede e sistema de arquivos. Na nuvem, revise IAM, exposição pública e permissões de metadados.' }],
  7: [{ heading: 'Continuidade e recuperação', body: 'A análise de impacto identifica serviços críticos, dependências e prioridades de retomada. Planos de continuidade mantêm funções essenciais; recuperação de desastre restaura tecnologia e dados. RTO mede tempo-alvo para restabelecer; RPO mede a perda temporal de dados tolerada. Exercícios revelam lacunas que documentos sozinhos não mostram.' }],
  8: [{ heading: 'Resposta a engenharia social', body: 'Phishing pode usar urgência, autoridade ou familiaridade para induzir clique, pagamento ou entrega de credenciais. Verifique domínio e canal por meio independente, reporte mensagens suspeitas e preserve evidências. Controles técnicos como MFA, filtragem e proteção de endpoint complementam treinamento e procedimentos de resposta.' }],
  9: [{ heading: 'Detecção, prevenção e teste', body: 'Firewall aplica regras de tráfego; IDS identifica padrões suspeitos; IPS pode bloquear; EDR acompanha atividade no endpoint. Varredura busca vulnerabilidades conhecidas em escala, enquanto pentest autorizado tenta validar caminhos de exploração e impacto. Defina escopo, autorização, janela, tratamento de dados e comunicação dos achados.' }],
  10: [{ heading: 'Verificação contextual', body: 'Uma arquitetura Zero Trust avalia cada solicitação considerando identidade, dispositivo, recurso, contexto e política; segmentação limita movimento lateral. A rede interna não é, por si só, evidência de confiança. A decisão deve ser explícita, de menor privilégio, registrada e reavaliada conforme risco.' }],
  11: [{ heading: 'SGSI e seleção de controles', body: 'A ISO/IEC 27001 trata do sistema de gestão: contexto, liderança, planejamento, suporte, operação, avaliação e melhoria contínua, com escopo e riscos definidos. A ISO/IEC 27002 fornece orientação sobre controles. A organização justifica seleção e aplicabilidade; adotar um catálogo não significa implementar todos sem análise.' }],
};
const securityClassroom: Array<[string, string, string]> = [
  ['Confidencialidade restringe quem vê; integridade detecta ou evita alteração indevida; disponibilidade permite uso oportuno. Autenticidade confirma origem ou identidade; não repúdio relaciona ações a evidências, políticas e contexto jurídico.', 'Para um relatório sigiloso, controle de acesso e criptografia em trânsito apoiam confidencialidade; hash ou assinatura pode apoiar integridade; redundância e recuperação apoiam disponibilidade. Nenhum controle isolado cobre todos os objetivos.', 'Criptografia não garante disponibilidade e backup não garante confidencialidade. Hash não autentica origem sem chave/controle adicional. Diferencie objetivo de segurança do mecanismo que pode contribuir para alcançá-lo.'],
  ['Risco relaciona evento, probabilidade e impacto segundo método definido; ameaça pode explorar vulnerabilidade; incidente é evento que compromete ou ameaça segurança. Avaliação prioriza tratamento e risco residual, não busca eliminar toda incerteza.', 'Inventarie ativos, ameaças e controles; estime impacto e probabilidade; escolha evitar, reduzir, compartilhar ou aceitar; atribua responsável e prazo. Reavalie após mudança de sistema, exposição ou ameaça.', 'Vulnerabilidade é fraqueza, não o risco inteiro. Aceitar risco exige autoridade e registro. Uma vulnerabilidade crítica exposta pode merecer prioridade, mas impacto, exploração e controles compensatórios entram na decisão.'],
  ['Classificação deve traduzir sensibilidade em tratamento prático durante criação, uso, compartilhamento, armazenamento e descarte. Regras precisam alcançar cópias, exportações, backups, logs e mídia removível.', 'Se um relatório contém dado pessoal e achado sensível, aplique rótulo e controles compatíveis; limite exportação e compartilhamento e revise retenção. Uma cópia temporária em pasta sincronizada também precisa herdar proteção.', 'Rótulo isolado não protege o conteúdo. “Interno” não equivale necessariamente a classificação legal. A classificação pode mudar conforme agregado, finalidade e contexto; evite expor demais e mantenha acesso necessário ao trabalho.'],
  ['IAM cobre identidade e seu ciclo: ingresso, mudança de função, revisão e desligamento. Autenticação verifica identidade; autorização decide operação; auditoria evidencia uso. RBAC usa papéis; ABAC considera atributos e contexto.', 'Analista pode ler processos da unidade, mas não administrar usuários. Ao mudar de área, retire permissões antigas e conceda apenas as novas necessárias. Conta de serviço deve ter dono, escopo, rotação e monitoramento.', 'MFA reduz certos riscos de senha roubada, mas não substitui autorização. Uma conta autenticada pode estar comprometida. Contas compartilhadas prejudicam atribuição; aplique segregação de funções para operações críticas.'],
  ['Cifra simétrica usa chave compartilhada e é eficiente; assimétrica usa par público/privado e facilita mecanismos de troca/assinatura. Hash é resumo unidirecional. Certificado vincula chave pública a identidade dentro de uma cadeia de confiança.', 'TLS autentica o servidor com certificado e negocia chaves de sessão; depois usa cifra simétrica para proteger tráfego. Assinatura digital usa chave privada e validação pública para apoiar integridade e autoria.', 'Hash sozinho não cifra nem prova autor. Assinatura não esconde conteúdo. Certificado expirado ou revogado muda validação; algoritmo forte não compensa chave privada exposta ou cadeia não confiável.'],
  ['OWASP Top 10 organiza classes de risco observadas e conscientiza; não é inventário completo de controles. A defesa deve partir de requisitos, threat modeling, práticas de codificação, teste e monitoramento.', 'Para quebrar acesso por objeto, teste usuário A requisitando identificador do usuário B; autorização deve ser conferida no servidor para cada ação. Teste também configuração, dependências, autenticação e tratamento de erros.', 'Ocultar botão não é controle de acesso. Passar Top 10 não prova conformidade completa. Use ASVS ou requisitos verificáveis para controles detalhados e atualize a referência conforme a versão pedida no edital.'],
  ['API deve validar esquema e tamanho, autenticar e autorizar cada recurso, limitar taxa, proteger segredo, tratar erro e registrar evento útil. Container reduz isolamento se roda privilegiado ou compartilha segredo sem necessidade.', 'Configure endpoint para checar escopo e propriedade do objeto no servidor; aplique rate limit e limite de payload. Em container, use imagem confiável, usuário não-root, filesystem mínimo e rede restrita.', 'CORS controla acesso de navegador entre origens; não autentica clientes arbitrários. Token válido não autoriza todo objeto. Container não elimina vulnerabilidades do kernel nem risco de imagem comprometida; atualize e monitore.'],
  ['Continuidade identifica processo essencial e meios para mantê-lo; recuperação de desastre restaura tecnologia e dados. BIA avalia impacto, dependências e prioridades. Plano deve indicar papéis, comunicação, recursos alternativos e critérios de retorno.', 'Se RPO é 15 minutos, a estratégia precisa limitar perda temporal de dados a esse objetivo; se RTO é 4 horas, exercite recuperação dentro desse prazo. Teste consistência do dado e integração com identidade e rede.', 'RPO mede perda de dados tolerada, não o tempo para restaurar. RTO mede tempo-alvo de restabelecimento. Backup ajuda, mas continuidade inclui processos e pessoas; só teste de restauração revela se a cópia é utilizável.'],
  ['Phishing imita remetente ou serviço para induzir clique, credencial ou pagamento; ransomware pode criptografar ou exfiltrar dados; engenharia social manipula confiança, urgência e autoridade. Vetores podem combinar técnica e comportamento.', 'Mensagem urgente pede validar domínio, destinatário, link e contexto; confirme pagamento por canal independente e reporte suspeita. Se houver clique, isole conforme procedimento e preserve evidências em vez de apagar rastros.', 'Treinamento é complementar, não substitui MFA, filtragem, atualização e resposta. Nem toda fraude contém anexo malicioso. Culpar usuário reduz reporte; cultura de comunicação rápida melhora contenção.'],
  ['Firewall controla tráfego por regras; IDS detecta e alerta; IPS pode bloquear; EDR observa e responde no endpoint. Scanner identifica vulnerabilidades conhecidas; pentest autorizado valida exploração possível e impacto sob escopo.', 'Scanner cobre muitos ativos com repetição; pentest prioriza caminhos e combinações exploráveis. Defina escopo, janela, autorização, dados de teste, contato de emergência e forma de validar correção.', 'Pentest não é varredura irrestrita nem garantia de ausência de falha. IDS geralmente detecta; IPS pode prevenir, mas implementação varia. Firewall não corrige vulnerabilidade da aplicação nem substitui controle de identidade.'],
  ['Zero Trust remove confiança implícita baseada apenas em rede ou localização. Política verifica identidade, dispositivo, recurso e contexto; privilégio mínimo e segmentação limitam movimento lateral; decisão pode ser reavaliada continuamente.', 'Mesmo conectado à VPN, um usuário prova identidade e recebe apenas acesso à aplicação necessária. Uma mudança de risco do dispositivo pode reduzir ou bloquear acesso conforme política e evidência.', 'Zero Trust não significa negar todo acesso nem comprar um produto específico. A rede interna não prova confiabilidade. Identidade, telemetria, política, segmentação e gestão de ativos precisam operar em conjunto.'],
  ['ISO/IEC 27001 estabelece requisitos para sistema de gestão de segurança com escopo, avaliação de risco, controles, auditoria e melhoria; ISO/IEC 27002 orienta seleção e implementação de controles. A declaração de aplicabilidade documenta decisões e justificativas.', 'Uma organização define escopo do SGSI, avalia riscos, escolhe tratamentos, documenta controles aplicáveis, monitora eficácia e audita. O catálogo da 27002 apoia controles, mas seleção depende de risco e contexto.', 'Certificação cobre escopo e período auditados, não prova segurança absoluta. ISO 27002 não é, por si só, norma de certificação equivalente à 27001. Versão e emendas precisam ser conferidas no material do edital.'],
];
const operations: Seed[] = [
  ['Windows e Linux oferecem usuários, permissões, processos, serviços, logs e mecanismos de atualização. Administração segura inclui contas individuais, privilégio mínimo, patching, configuração endurecida e monitoramento.', 'Desative serviço sem uso, atualize pacotes e registre acesso administrativo.', 'Executar toda administração como usuário privilegiado amplia o impacto de erro ou comprometimento.', 'certo', 'Privilégio mínimo reduz superfície e alcance de incidentes.'],
  ['Processo é instância em execução; memória contém código e dados com espaços e permissões; sistema de arquivos organiza nomes, diretórios, metadados e permissões. Contenção e isolamento protegem recursos.', 'Permissões Unix separam leitura, escrita e execução para dono, grupo e outros.', 'Memória virtual permite ao sistema abstrair e gerenciar espaço de endereçamento dos processos.', 'certo', 'A abstração de memória virtual separa endereços lógicos da memória física.'],
  ['Shell interpreta comandos e permite encadeamento, redirecionamento e scripts. Linux usa shells como Bash; PowerShell opera com objetos e cmdlets. Scripts devem validar entradas, citar variáveis, tratar erros e evitar segredos embutidos.', 'Um pipeline PowerShell pode passar objetos entre cmdlets; uma pipeline Unix costuma conectar fluxos de texto/bytes.', 'PowerShell e shells Unix têm sintaxe e modelo de dados idênticos.', 'errado', 'Há diferenças importantes, inclusive passagem de objetos estruturados no pipeline PowerShell.'],
  ['Active Directory organiza identidades, computadores e políticas em domínio Windows; LDAP é protocolo para acessar e consultar diretórios. Integração exige proteção de credenciais, TLS, controle de bind e autorização por grupos/atributos.', 'Aplicação consulta diretório por conexão TLS usando conta com escopo de leitura limitado.', 'LDAP e Active Directory são sinônimos.', 'errado', 'LDAP é protocolo; Active Directory é serviço de diretório que suporta LDAP e outros mecanismos.'],
  ['Virtualização executa máquinas virtuais com sistemas convidados e hypervisor; containers isolam processos compartilhando kernel do host. VMs oferecem fronteira e kernel próprios; containers são mais leves, mas isolamento depende da configuração.', 'VM pode executar outro kernel; container normalmente compartilha kernel do host.', 'Containers eliminam a necessidade de atualizar o kernel hospedeiro.', 'errado', 'O kernel compartilhado continua sendo parte crítica e precisa de manutenção.'],
  ['TCP/IP organiza comunicação em camadas; IP endereça e encaminha datagramas; TCP oferece fluxo confiável e ordenado; UDP é datagrama sem garantias de entrega. IPv4 usa 32 bits; IPv6, 128 bits.', 'Uma aplicação pode usar TCP para sessão confiável; serviços de voz podem escolher UDP com tolerância a perdas.', 'TCP e IP são protocolos de camadas diferentes e cumprem funções complementares.', 'certo', 'IP encaminha; TCP fornece serviço de transporte orientado a conexão.'],
  ['DNS traduz nomes em registros; DHCP distribui configuração de rede; HTTP/2 multiplexa streams sobre conexão; HTTP/3 usa QUIC sobre UDP; HTTPS protege HTTP com TLS. SMTP envia correio; FTP transfere arquivos; SSH oferece acesso remoto seguro.', 'DNS A/AAAA associa nome a endereço IPv4/IPv6; DHCP pode fornecer endereço e gateway.', 'HTTPS é HTTP protegido por TLS, não um protocolo totalmente independente de HTTP.', 'certo', 'HTTPS aplica segurança de transporte ao tráfego HTTP.'],
  ['VPN cria túnel protegido; balanceador distribui requisições; proxy intermedeia comunicação; firewall aplica política de tráfego; redes sem fio usam rádio e autenticação. Desenho deve considerar segmentação, disponibilidade e proteção de credenciais.', 'VPN remota pode proteger tráfego até a rede corporativa, mas não elimina necessidade de autenticação e autorização.', 'Uma VPN torna todo endpoint conectado automaticamente confiável.', 'errado', 'Acesso ao túnel não deve substituir controles por identidade, dispositivo e recurso.'],
  ['IaaS fornece recursos computacionais; PaaS abstrai plataforma de execução; SaaS entrega aplicação como serviço; serverless abstrai gestão direta de servidores e escala por execução. Responsabilidade de segurança é compartilhada e varia por modelo.', 'Em IaaS o cliente tende a gerir mais componentes do sistema operacional que em SaaS.', 'Serverless significa que não há servidores físicos ou responsabilidades operacionais.', 'errado', 'Servidores existem; o provedor abstrai sua gestão direta, mas continuam controles de código, dados e configuração.'],
  ['Escalabilidade trata crescimento de capacidade; alta disponibilidade reduz interrupções por redundância e recuperação; integração híbrida combina ambientes locais e nuvem. Dependências, latência, consistência, identidade e conectividade devem ser planejadas.', 'Replicar aplicação em zonas distintas pode melhorar disponibilidade, mas banco e rede também precisam ser considerados.', 'Adicionar réplicas de aplicação garante sozinho alta disponibilidade ponta a ponta.', 'errado', 'Banco, rede, DNS, dependências e operação podem continuar como pontos únicos de falha.'],
  ['Monitoramento coleta sinais de saúde e capacidade de infraestrutura: CPU, memória, disco, rede, processos, serviços e eventos. Baselines, limiares, retenção e alertas acionáveis permitem antecipar saturação e investigar falhas.', 'Alerta de disco deve considerar tendência e espaço disponível, com ação e responsável definidos.', 'Monitoramento e observabilidade são complementares, mas monitoramento normalmente verifica condições conhecidas.', 'certo', 'Observabilidade também apoia inferência de causas não previstas a partir de sinais.'],
];
const operationsSections: Record<number, Array<{ heading: string; body: string }>> = {
  0: [{ heading: 'Administração segura', body: 'Separe conta de uso cotidiano da conta administrativa, aplique atualização com janela e plano de retorno, centralize logs e restrinja serviços expostos. Em Windows e Linux, permissões, grupos, políticas e serviços são controles complementares; o nome do sistema não substitui o princípio do menor privilégio.' }],
  1: [{ heading: 'Processos, memória e arquivos', body: 'O sistema operacional agenda processos e threads, mapeia memória virtual para memória física e aplica proteção entre espaços de endereçamento. No sistema de arquivos, nome e conteúdo não esgotam os metadados: permissões, proprietário, timestamps e links também influenciam acesso e administração.' }],
  2: [{ heading: 'Shell e automação', body: 'Shells conectam comandos por entrada e saída, redirecionam fluxos e permitem repetição por scripts. Valide argumentos, trate códigos de saída e erros, evite interpolação insegura e proteja credenciais. No PowerShell, cmdlets normalmente passam objetos estruturados; em shells Unix, pipelines tradicionalmente passam fluxos de texto/bytes.' }],
  3: [{ heading: 'Diretório e protocolo', body: 'Active Directory organiza objetos, domínios e políticas de um ambiente Windows. LDAP define operações e formato para consultar ou modificar diretórios; diferentes produtos podem implementá-lo. Prefira LDAPS ou StartTLS quando aplicável, contas de serviço restritas e consultas com parâmetros validados.' }],
  4: [{ heading: 'Máquinas virtuais e containers', body: 'O hypervisor distribui recursos a sistemas convidados com kernel próprio; snapshots não substituem backup consistente. Containers isolam processos, namespaces e recursos, compartilhando o kernel do host. Isso reduz sobrecarga, mas torna atualização do host, isolamento, privilégios e origem da imagem relevantes para a segurança.' }],
  5: [{ heading: 'Endereçamento e transporte', body: 'IPv4 usa endereço de 32 bits e IPv6 de 128; máscaras e prefixos definem redes e hosts. TCP fornece fluxo confiável e ordenado, com conexão e controle de congestionamento; UDP oferece datagramas sem garantia de entrega ou ordem. Aplicações escolhem conforme latência, confiabilidade e protocolo usado.' }],
  6: [{ heading: 'Serviços e portas', body: 'DNS resolve nomes; DHCP distribui configuração de rede; SMTP transfere mensagens; SSH permite administração remota protegida. HTTP/2 multiplexa requisições sobre uma conexão TCP, enquanto HTTP/3 usa QUIC sobre UDP. HTTPS protege comunicação HTTP com TLS, mas não garante que o conteúdo ou o servidor sejam confiáveis por si sós.' }],
  7: [{ heading: 'Controles de rede', body: 'VPN protege um túnel entre pontos; proxy intermedeia requisições; balanceador distribui carga; firewall aplica política de tráfego. Esses componentes não substituem autenticação forte, autorização e atualização dos endpoints. Redes sem fio também dependem de criptografia, configuração, segmentação e gestão segura das credenciais.' }],
  8: [{ heading: 'Responsabilidade compartilhada', body: 'Em IaaS, o cliente administra mais componentes, como sistema operacional e aplicações; em PaaS, o provedor gerencia parte da plataforma; em SaaS, entrega a aplicação gerenciada. Em qualquer modelo, o cliente continua responsável por aspectos como dados, identidade, configuração e uso adequado do serviço.' }],
  9: [{ heading: 'Disponibilidade ponta a ponta', body: 'Escala horizontal adiciona instâncias; vertical amplia recursos de uma instância. Alta disponibilidade combina redundância, detecção e recuperação, mas deve cobrir dependências como DNS, armazenamento, rede, banco e identidade. Em integração híbrida, planeje latência, conectividade, sincronização e falha de cada lado.' }],
  10: [{ heading: 'Operação por sinais', body: 'Defina métricas de utilização e saturação, logs com contexto e alertas que indiquem ação. Baseline ajuda a distinguir variação normal de anomalia; capacidade deve considerar tendência e sazonalidade. Monitorar não é apenas coletar: retenção, acesso aos registros e procedimento de resposta também precisam ser definidos.' }],
};
const operationsClassroom: Array<[string, string, string]> = [
  ['Windows e Linux administram contas, permissões, serviços e atualizações com ferramentas e modelos próprios. Conta padrão separada da administrativa limita impacto; patching reduz exposição conhecida; hardening desativa funções desnecessárias.', 'Crie usuário individual, use elevação temporária para tarefa administrativa, aplique atualização testada, revise serviço exposto e confirme log de acesso. Em Windows, políticas e grupos podem centralizar configurações; em Linux, usuários, grupos e permissões sustentam controles.', 'Executar tudo como root/administrador facilita operação, mas amplia dano de erro ou malware. Atualização sem janela ou retorno pode interromper serviço. Não confunda hardening com simples instalação de antivírus.'],
  ['Processo é programa em execução com contexto e recursos; thread é fluxo de execução no processo. Memória virtual oferece espaço de endereçamento isolado; sistema de arquivos organiza nomes, conteúdo e metadados com permissões.', 'Ao diagnosticar lentidão, verifique CPU, memória, page faults, disco e processos. Permissão Unix combina leitura, escrita e execução para usuário, grupo e outros; propriedade e ACL podem ampliar controle.', 'Memória virtual não é memória física adicional infinita. Processo e thread não são sinônimos. Apagar arquivo pode não liberar espaço se processo mantém descritor aberto; metadados e links também afetam administração.'],
  ['Shell lê comandos, expande variáveis e encadeia processos. Redirecionamento envia entrada/saída a arquivos ou canais. Bash e shells Unix normalmente passam fluxos; PowerShell passa objetos estruturados entre cmdlets.', 'Em um script, valide argumentos, use caminhos delimitados, confira exit code e trate falhas. Um pipeline PowerShell pode selecionar propriedade de objeto; em Bash, filtros frequentemente interpretam texto e exigem quoting cuidadoso.', 'Não concatene entrada não confiável em comando; pode ocorrer command injection. Não suponha que aspas e operadores sejam iguais entre shells. Segredo embutido em script pode vazar por repositório, log ou histórico.'],
  ['Active Directory organiza objetos, usuários, computadores, grupos e políticas em domínios; LDAP é protocolo para consultar e modificar diretórios. Autenticação e autorização podem integrar grupos e atributos, mas exigem comunicação protegida e consulta segura.', 'Uma aplicação usa conta de serviço com leitura limitada, conexão TLS e bind apropriado; consulta grupos para decidir acesso no sistema, sem expor senha no log.', 'LDAP não é o próprio Active Directory; há outros diretórios compatíveis. Criptografar transporte não corrige privilégio excessivo. Valide filtros para evitar injeção LDAP e proteja credenciais de bind.'],
  ['Hypervisor aloca CPU, memória e dispositivos a máquinas virtuais, cada qual com sistema convidado. Containers isolam processos e recursos do host e normalmente compartilham o kernel. Snapshot registra estado pontual e não substitui backup confiável.', 'VM é adequada quando precisa de kernel/ambiente diferente; container empacota serviço leve e reproduzível. Separe redes e volumes e limite privilégios em ambos; mantenha hipervisor e kernel do host atualizados.', 'Containers não trazem kernel próprio nem eliminam atualização do hospedeiro. VM também não é automaticamente segura se configuração, rede ou imagem estiverem comprometidas. Snapshot pode capturar corrupção e não substitui cópia externa.'],
  ['IP entrega datagramas entre redes; roteamento usa prefixos. IPv4 tem 32 bits e IPv6 128. TCP provê fluxo ordenado e confiável com controle de congestionamento; UDP provê datagramas sem garantia de ordem ou entrega.', 'Em IPv4, endereço e máscara/prefixo identificam rede e hosts; em IPv6, prefixo faz papel de divisão. Aplicação pode escolher TCP para integridade de fluxo ou UDP para baixa latência e tolerância a perda, adicionando controles se necessários.', 'IP não garante entrega. TCP não entende significado de mensagem de negócio e uma conexão não garante disponibilidade da aplicação. UDP não é sempre mais rápido; perda, retransmissão no aplicativo e congestionamento devem ser considerados.'],
  ['DNS resolve nomes e tipos de registro; DHCP distribui endereço e parâmetros. HTTP/2 multiplexa streams sobre TCP; HTTP/3 usa QUIC sobre UDP; HTTPS é HTTP protegido por TLS. SMTP envia mensagens; FTP transfere arquivos; SSH oferece canal remoto seguro.', 'Ao abrir site, cliente pode resolver DNS, estabelecer transporte, negociar TLS e enviar HTTP. Falha em cada etapa gera sintomas distintos. A/AAAA indicam endereços IPv4/IPv6; MX aponta servidores de correio.', 'DNS não é DHCP; HTTPS não garante conteúdo legítimo, só protege conexão conforme validação. HTTP/3 usa QUIC, não TCP diretamente. FTP tradicional não protege credenciais por padrão; SSH não é protocolo de transferência idêntico a FTP.'],
  ['VPN encapsula e protege tráfego entre pontos; proxy faz mediação; balanceador distribui carga; firewall aplica política; Wi-Fi conecta por rádio com autenticação e criptografia. Segmentação delimita alcance e facilita controle.', 'Use VPN para proteger túnel remoto, proxy para controlar/registrar navegação e balanceador para distribuir conexões. Mesmo assim, autentique usuário e serviço, valide certificado, proteja endpoint e limite rotas autorizadas.', 'VPN não transforma dispositivo infectado em confiável. Proxy não é necessariamente firewall. Balanceamento não elimina gargalo de banco. CORS é navegador; firewall controla tráfego em outro nível. Segurança sem fio depende de configuração e credenciais fortes.'],
  ['IaaS oferece recursos de computação; PaaS administra mais plataforma; SaaS entrega aplicação gerenciada. Serverless abstrai provisão direta de servidor e escala execução, mas há infraestrutura subjacente e responsabilidades do cliente.', 'Em IaaS, cliente costuma corrigir sistema operacional; em PaaS, gerencia aplicação e dados; em SaaS, administra usuários, acesso, dados e configuração. O modelo concreto e contrato podem alterar fronteiras.', '“Nuvem” não significa responsabilidade zero. Provedor protege componentes sob seu controle; cliente continua responsável por dados, identidade, configuração e uso. Serverless pode ter limite de execução, cold start e dependência do provedor.'],
  ['Escala vertical aumenta recurso de instância; horizontal adiciona instâncias. Alta disponibilidade combina redundância, detecção, failover e recuperação, cobrindo dependências. Integração híbrida conecta ambiente local e nuvem com identidade, rede, dados e operação coerentes.', 'Desenhe dependências do serviço: DNS, autenticação, banco, storage e rede. Elimine ponto único de falha quando necessário, teste failover e confira consistência. Na nuvem híbrida, estime latência e comportamento sob perda de conectividade.', 'Réplicas de aplicação não garantem disponibilidade se banco ou DNS for único. Failover pode produzir split brain ou dados desatualizados. Alta disponibilidade e recuperação de desastre tratam objetivos e escalas diferentes.'],
  ['Monitoramento coleta métricas, logs e estado de componentes para verificar condições conhecidas. Baseline caracteriza comportamento normal; capacidade prevê saturação; alertas encaminham sintomas acionáveis com prioridade e dono.', 'Observe CPU, memória, espaço, rede, processos, fila e erros. Tendência de disco pode alertar antes do limite; inclua janela, crescimento e tempo de resposta. Combine alertas com runbook e política de escalonamento.', 'Coletar tudo sem retenção e finalidade gera custo e risco. Monitoramento indica condição observada, mas não explica toda causa; investigação cruza sinais. Defina acesso a logs e proteja dados pessoais ou credenciais presentes nos registros.'],
];

export const INFRASTRUCTURE_CONTENT: Record<string, Lesson> = {
  ...Object.fromEntries(security.map((seed, index) => { const id = `seguranca-${index}`; const [mechanics, application, examFocus] = securityClassroom[index]; const lesson = make(id, seed, 'OWASP Top 10:2025', 'https://top10.owasp.org/2025/pt-BR/'); return [id, { ...lesson, lessonSections: [...securitySections[index], { heading: 'Funcionamento em detalhe', body: mechanics }, { heading: 'Aplicação passo a passo', body: application }, { heading: 'Distinções e armadilhas', body: examFocus }] }]; })),
  ...Object.fromEntries(operations.map((seed, index) => { const id = `so-redes-nuvem-${index}`; const [mechanics, application, examFocus] = operationsClassroom[index]; const lesson = make(id, seed, 'MDN — visão geral de HTTP', 'https://developer.mozilla.org/pt-BR/docs/Web/HTTP/Overview'); return [id, { ...lesson, lessonSections: [...operationsSections[index], { heading: 'Funcionamento em detalhe', body: mechanics }, { heading: 'Aplicação passo a passo', body: application }, { heading: 'Distinções e armadilhas', body: examFocus }] }]; })),
};
